INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(95606, 'ruRU', '', 'В атаку!', 24330),
(95607, 'ruRU', '', 'Атаковать!', 24330),
(95608, 'ruRU', '', 'Ай!', 24330),
(95609, 'ruRU', '', 'Прибыл для несения службы!', 24330),
(95610, 'ruRU', '', 'Готов выступать!', 24330),
(95615, 'ruRU', '', 'Главным орудиям приготовиться ко второму залпу, как только мы пробьём облачный покров.', 24330),
(95635, 'ruRU', '', 'Ты хорошо вёл нас до сих пор, $n — не вижу причин менять курс сейчас.', 24330),
(95636, 'ruRU', '', 'Я отправляюсь в Даларан искать паладинов, достойных присоединиться к нашему делу. Рыцари, оставайтесь здесь на случай, если $n что-то понадобится, пока меня нет.', 24330),
(95638, 'ruRU', '', 'Элуна, благослови мою стрелу. Пусть прицел будет верным!', 24330),
(95639, 'ruRU', '', 'Захватчик, этот мир не падёт перед такими, как ты!', 24330),
(95640, 'ruRU', '', 'Незваные гости! Калдорай защищают эти земли.', 24330),
(95641, 'ruRU', '', 'Вы уничтожили бесчисленные миры, но мы не падём так легко.', 24330),
(95642, 'ruRU', '', 'Именем Азшары, прочь из этого места!', 24330),
(95643, 'ruRU', '', 'Мой клинок остёр, а стрела быстра. Мы не станем лёгкой добычей.', 24330),
(95650, 'ruRU', '', 'Вон там у Амелии снаряжение куда лучше того, что могу предложить я, если собираешься биться с Ордой.', 24330),
(95651, 'ruRU', '', 'Тебе стоит поговорить с Холли МакТилла, если хочешь сразиться с лучшим, что может выставить Орда. И ещё спроси у неё, кто делает ей причёску, ладно?', 24330),
(95656, 'ruRU', '', 'Айндеру! Что скажешь об этой ткани?', 24330),
(95659, 'ruRU', '', 'Поразительно...', 24330),
(95663, 'ruRU', '', 'Мы всегда откликнемся на зов Света. Дай нам знать, где мы нужны.', 24330),
(95666, 'ruRU', '', 'Именно Кладд Странник Рассвета поможет тебе, если хочешь получить награды высочайшего качества за свою доблесть в бою.', 24330),
(95667, 'ruRU', '', 'Именно Тэй''локс Иссушитель Душ поможет тебе, если хочешь получить награды высочайшего качества за свою доблесть в бою.', 24330),
(95668, 'ruRU', '', 'Да-да, знаю, мой товар не так хорош, как то, что продаёт Тэй''локс. Но знаешь что, зато он симпатичнее, разве нет? Как это ты думаешь, что он выглядит так же? Он ЯВНО другой! Неблагодарный бездельник! Тебе повезло, что мой контракт всё ещё в силе.', 24330),
(95674, 'ruRU', '', 'Не могу поверить, что этой простолюдинке Холли МакТилла доверили лучшее оружие и броню. Дворфийке! Честно говоря, неудивительно, что мы до сих пор не взяли этот остров.', 24330),
(95681, 'ruRU', '', 'Нужно поспешить. Легион может напасть в любой момент.', 24330),
(95690, 'ruRU', '', 'Нельзя терять время. Вперёд!', 24330),
(95692, 'ruRU', '', 'Призыв? Конечно! Где, говоришь, он находится?', 24330),
(95693, 'ruRU', '', 'Секунду... вот! Я его поймал!', 24330),
(95697, 'ruRU', '', 'Вовсе нет. Располагайся, как дома.', 24330),
(95698, 'ruRU', '', 'Уверен, мы многому можем научиться друг у друга.', 24330),
(95700, 'ruRU', '', 'Добро пожаловать в "Картье и Компания, изысканные украшения", $c. Сразу видно — ты ценишь утончённые вещи.$b$bЧто тебе сегодня показать?', 24330),
(95703, 'ruRU', '', 'Готово! Передай Танитрии, что она должна мне ещё одну шёлковую подушку.', 24330),
(95704, 'ruRU', '', 'Проще простого...', 24330),
(95723, 'ruRU', '', 'Книги. Да, тома Гул''дана. Ты уверен, что Кадгар не пытался ими воспользоваться?', 24330),
(95724, 'ruRU', '', 'Книги силы... книги знаний... книги, написанные на языке хаоса... Не волнуйся, защитник, все они будут уничтожены.', 24330),
(95725, 'ruRU', '', 'А теперь отдай мне своё кольцо. Оно мне нужно. Дай сюда!', 24330),
(95727, 'ruRU', '', 'Тогда я ЗАБЕРУ его у тебя! Во славу Гул''дана!', 24330),
(95728, 'ruRU', '', 'Сфера Господства говорила со мной. Я узрел ИСТИНУ.', 24330),
(95729, 'ruRU', '', 'Кадгар — просто ребёнок, который важничает, пытает своих пленников, играет жизнями, балуется магией, которую делает вид, что понимает.', 24330),
(95730, 'ruRU', '', 'Такова сила Легиона!', 24330),
(95731, 'ruRU', '', 'Что ж, уходи. Ничто не остановит Гул''дана, ведь за ним стоит Легион. Запомни мои слова: твои вожди предадут тебя. АЗЕРОТ СГОРИТ.', 24330);
